void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 r = fragCoord/iResolution.xy;
    vec3 col;

//    float E = clamp(texture(iChannel0, r).z/10., 0., 1.);
//    float E = texture(iChannel0, r).z;

//    E += draw_string(iChannel0,r*vec2(31,12)-vec2(3,2), line1);

    // Output to screen
    float E = texture(iChannel0, r).z;
    float f = 3.*E;
    col = vec3(dist(-f-0.5, .1),
                exp(-1.*pow(f,2.)),
                dist(f-0.5, .1));
//    col = vec3(E, float(E<0.), float(E>1.));
    fragColor = vec4(col, 1.);

}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    ivec3 d_ir = ivec3(1,1,0);
    vec2 r = fragCoord;
    vec2 r0 = iResolution.xy/2.;
    vec2 m  = iMouse.xy;

    float cx = a*dt/dx;
    float cy = a*dt/dy;
    float Ez;

    ivec2 ir = ivec2(fragCoord);
    if(iFrame == 0)
    { 
        Ez = smoothstep(1.,0.,length((r-r0)/REGION_SIZE));
//        Ez = 0.;
    }
    else
    {
        Ez = texelFetch(iChannel0, ir, 0).z; 

        float dHy_dx = (texelFetch(iChannel1, ir + d_ir.xz, 0).y
                      - texelFetch(iChannel1, ir, 0).y)*cx;
        float dHx_dy = (texelFetch(iChannel1, ir + d_ir.zy, 0).x
                      - texelFetch(iChannel1, ir, 0).x)*cy;

        Ez += dHy_dx - dHx_dy; 

//    float t = float(iFrame)*dt;
//    Ez += float(is_in_ellipse(r-r0, REGION_SIZE))*sin(0.02*t);

        if(sign(iMouse.w) > 0.)
            Ez += smoothstep(1.,0.,length((r-m)/REGION_SIZE));

    }

    fragColor.z = Ez*.99;
}

#define SKIP_FRAMES 10

#define dx .1
#define dy .1

#define a 1.

const float dt = 1./2.*0.99*sqrt(dx*dx + dy*dy)/a;

#define REGION_SIZE vec2(25,25)

bool is_in_ellipse(vec2 uv, vec2 size){
    return length(uv/size) < 1.;
}


float dist(float _x, float _dx){
    return 1./(1.+exp(-_x/_dx));
}


float random_drop(float t, vec2 pos, vec2 Res){
    pos -= fract(floor(t)*vec2(0.456665,0.708618))*Res;
    float amp = 1. - step(.05, fract(t));

    return amp*smoothstep(20.,5.,length(pos));
}

