void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    ivec3 dr = ivec3(1,1,0);
    vec2 r = fragCoord;
    vec2 r0 = iResolution.xy/2.;
    vec2 m  = iMouse.xy;

    float cx = a*dt/dx;
    float cy = a*dt/dy;
    float Hx, Hy;


    ivec2 coords = ivec2(fragCoord);
    if(iFrame == 0)
    { 
        fragColor.x = 0.;
        fragColor.y = 0.;
    }
    else
    {
        Hx = texelFetch(iChannel0, coords, 0).x; 
        Hy = texelFetch(iChannel0, coords, 0).y; 

        float dEz_dx = (texelFetch(iChannel1, coords, 0).z
                      - texelFetch(iChannel1, coords - dr.xz, 0).z)*cx;
        float dEz_dy = (texelFetch(iChannel1, coords, 0).z
                      - texelFetch(iChannel1, coords - dr.zy, 0).z)*cy;

        Hx += -dEz_dy; 
        Hy += dEz_dx; 

        fragColor.x = Hx*.99;
        fragColor.y = Hy*.99;
    }

}
